import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("tmpf");
  const mk = async (o: any) => {
    const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    return issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, o), ...o }, t.userIds.owner, n);
  };
  const l1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "a", color: "#ef4444", description: null });
  const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "b", color: "#ef4444", description: null });
  const both = await mk({ title: "both", labelIds: [l1.id, l2.id], assigneeId: t.userIds.member, dueAt: "2026-03-01T15:00:00.000Z", status: "done" });
  const one = await mk({ title: "one", labelIds: [l1.id] });
  const arch = await mk({ title: "arch" });
  await issueRepo.archiveIssue(t.org.id, arch.id);
  const q = (f: any) => issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, ...f });
  let p = await q({ labelIds: [l1.id, l2.id] });
  expect(p.items.map((i) => i.id)).toEqual([both.id]); expect(p.total).toBe(1);
  p = await q({ assigneeId: null }); expect(p.items.map(i=>i.id)).not.toContain(both.id); expect(p.total).toBe(1 + 0 + 0 - 0 + 0 || 1);
  p = await q({ dueBefore: "2026-03-01" }); expect(p.items.map(i=>i.id)).toEqual([both.id]);
  p = await q({ dueBefore: "2026-03-01T15:00:00.000Z" }); expect(p.total).toBe(0);
  p = await q({ dueBefore: "2026-02-28" }); expect(p.total).toBe(0);
  p = await q({ includeArchived: "only" }); expect(p.items.map(i=>i.id)).toEqual([arch.id]); expect(p.total).toBe(1);
  p = await q({ status: ["closed"] }); expect(p.items.map(i=>i.id)).toEqual([both.id]);
  p = await q({ status: ["open"] }); expect(p.items.map(i=>i.id)).toEqual([one.id]);
});
EOF
